import { Injectable, inject } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';
import { Image, Note, Tag, Verse } from '../common/verse/verse';

@Injectable({
  providedIn: 'root',
})
export class VerseService {
  private supabaseClient = inject<SupabaseClient<Database>>(SupabaseClient);


  async getVerse(id: number) {
    const { data, error } = await this.supabaseClient
      .from('verses')
      .select('*, notes(*), images(*)')
      .eq('id', id)
      .single();

    if (error) {
      throw new Error(error.message);
    }

    // Fetch tags separately due to junction table
    const { data: verseTags } = await this.supabaseClient
      .from('verse_tags')
      .select('tags(*)')
      .eq('verse_id', id);

    const tags: Tag[] = verseTags
      ? verseTags.map((vt) => vt.tags as Tag).filter(Boolean)
      : [];

    return { ...data, tags } as Verse & { notes: Note[]; images: Image[]; tags: Tag[] };
  }
}
