import { CommonModule } from '@angular/common';
import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import {
  IonBackButton,
  IonButtons,
  IonCol,
  IonContent,
  IonFab,
  IonFabButton,
  IonFabList,
  IonGrid,
  IonHeader,
  IonRow,
  IonTitle,
  IonToolbar,
  ModalController,
  ViewWillEnter,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { close } from 'ionicons/icons';
import {
  BehaviorSubject,
  catchError,
  combineLatest,
  firstValueFrom,
  from,
  map,
  shareReplay,
  switchMap,
} from 'rxjs';
import { defaultBible } from 'supabase/functions/_shared/bibles';
import { ImageTheme, ImageThemeType } from 'supabase/functions/images/themes';
import { getRoutePath, favoritesRoutePath, searchRoutePath } from '../app.routes';
import { AlertService } from '../common/alert/alert.service';
import { ClipboardService } from '../common/clipboard/clipboard.service';
import { CreditsService } from '../common/credits/credits.service';
import { LoadingService } from '../common/loading/loading.service';
import { SkeletonCardComponent } from '../common/verse/skeleton-card/skeleton-card.component';
import { Image, Note, Tag } from '../common/verse/verse';
import { VerseCardComponent } from '../common/verse/verse-card/verse-card.component';
import {
  ImagesService,
  VeniceImageModel,
  resolveModel,
  getModelInfo,
} from '../images/images.service';
import { NotesService } from '../notes/notes.service';
import { AddImageCardComponent } from './add-image-card/add-image-card.component';
import { Attachment, ImageAttachment, NoteAttachment } from './attachment';
import { ImageAttachmentCardComponent } from './image-attachment-card/image-attachment-card.component';
import { NoteAttachmentCardComponent } from './note-attachment-card/note-attachment-card.component';
import { VerseQuoteFactory } from './verse-quote-factory/verse-quote-factory.service';
import { VerseService } from './verse.service';
import { TagPopupComponent } from '../common/tag-popup/tag-popup.component';

@Component({
  selector: 'app-verse',
  templateUrl: './verse.page.html',
  styleUrls: ['./verse.page.scss'],
  imports: [
    IonRow,
    IonGrid,
    IonCol,
    IonFabList,
    IonFabButton,
    IonFab,
    IonBackButton,
    IonButtons,
    IonContent,
    IonHeader,
    IonTitle,
    IonToolbar,
    CommonModule,
    FormsModule,
    SkeletonCardComponent,
    VerseCardComponent,
    AddImageCardComponent,
    ImageAttachmentCardComponent,
    NoteAttachmentCardComponent,
  ],
})
export class VersePage implements ViewWillEnter {
  private alertService = inject(AlertService);
  private clipboardService = inject(ClipboardService);
  private creditsService = inject(CreditsService);
  private loadingService = inject(LoadingService);
  private imagesService = inject(ImagesService);
  private modalCtrl = inject(ModalController);
  private notesService = inject(NotesService);
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private verseService = inject(VerseService);
  private verseQuoteFactory = inject(VerseQuoteFactory);

  readonly defaultHref = searchRoutePath;

  newNoteId = signal<number | null>(null);
  creditBalance = signal<number>(0);
  refresh$ = new BehaviorSubject<void>(undefined);

  verse$ = combineLatest([this.id$, this.refresh$]).pipe(
    switchMap(async ([id]) => this.verseService.getVerse(id)),
    map((verse) => verse),
    catchError((error: Error) => {
      const message = error.message || 'An error occurred';
      return from(
        this.alertService.createNotice({
          message,
          duration: 5000,
          positionAnchor: 'footer',
        })
      ).pipe(
        map(() => {
          return {
            id: 0,
            bible_id: defaultBible.id,
            book: '',
            chapter: 0,
            start_verse: 0,
            end_verse: 0,
            content: '',
            created_at: '',
            user_id: '',
            is_favorite: false,
            last_updated: '',
            notes: [],
            images: [],
            tags: [],
          };
        })
      );
    }),
    shareReplay(1)
  );

  attachments$ = this.verse$.pipe(
    map((verse) =>
      [
        ...this.createNoteAttachments(verse.notes),
        ...this.createImageAttachments(verse.images),
      ].sort(this.sortDescending)
    )
  );

  shouldShowAddImage = signal(false);

  fabIcons = {
    add: 'node_modules/openmoji/color/svg/2795.svg', // ➕ Plus Sign
    image: 'node_modules/openmoji/color/svg/1F5BC.svg', // 🖼️ Framed Picture
    pencil: 'node_modules/openmoji/color/svg/270F.svg', // ✏️ Pencil
    tag: 'node_modules/openmoji/color/svg/1F3F7.svg', // 🏷️ Label
  };

  constructor() {
    addIcons({ close });
  }

  async ionViewWillEnter() {
    this.refresh$.next();
    this.newNoteId.set(null);
    await this.loadCreditBalance();
  }

  private async loadCreditBalance() {
    const balance = await this.creditsService.getBalance();
    this.creditBalance.set(balance);
  }

  async addNote() {
    const id = await firstValueFrom(this.id$);
    this.loadingService.setLoading(true);

    try {
      const result = await this.notesService.insertNote({
        verse_id: id,
        content: '',
      });
      this.newNoteId.set(result.id);
      this.refresh$.next();
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : 'An error occurred';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
      });
    } finally {
      this.loadingService.setLoading(false);
    }
  }

  async editTags() {
    const id = await firstValueFrom(this.id$);

    const modal = await this.modalCtrl.create({
      component: TagPopupComponent,
      componentProps: {
        verseId: id,
      },
    });

    await modal.present();

    const { data } = await modal.onDidDismiss();

    if (data?.changed) {
      this.refresh$.next();
    }
  }

  async handleCreateImage({
    theme,
    veniceModel,
  }: {
    theme: ImageTheme;
    veniceModel: VeniceImageModel;
  }) {
    this.newNoteId.set(null);
    this.loadingService.setLoading(true);

    try {
      const verse = await firstValueFrom(this.verse$);
      if (!verse.content) {
        throw new Error('Verse content is empty');
      }

      // All images are now square
      const { quote, source } = this.verseQuoteFactory.create(verse, 'square');
      await this.imagesService.generateImage(
        verse.id!,
        quote,
        source,
        theme,
        veniceModel
      );
      this.refresh$.next();
      // Refresh credit balance after successful generation
      await this.loadCreditBalance();
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : 'An error occurred';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
      });
    } finally {
      this.loadingService.setLoading(false);
      this.shouldShowAddImage.set(false);
    }
  }

  async handleRemoveAttachment(attachment: Attachment) {
    try {
      this.loadingService.setLoading(true);

      if (attachment.type === 'Note') {
        await this.notesService.deleteNote(attachment.id);
      } else if (attachment.type === 'Image') {
        await this.imagesService.deleteImage(
          attachment.id,
          attachment.storage_path
        );
      }

      this.refresh$.next();
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : 'An error occurred';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
      });
    } finally {
      this.loadingService.setLoading(false);
    }
  }

  handleNoteEditingChange(isEditing: boolean, noteId: number) {
    // If editing is being turned off and this is the new note, reset newNoteId
    if (!isEditing && this.newNoteId() === noteId) {
      this.newNoteId.set(null);
    }

    // If editing is being turned off, refresh to get the latest content
    if (!isEditing) {
      this.refresh$.next();
    }
  }

  handleNoteUpdate(updatedNote: NoteAttachment) {
    // No need to refresh during auto-save while editing - this would reset the editing state
    // The refresh will happen when the user stops editing via handleNoteEditingChange
  }

  async handleVerseClick() {
    await this.alertService.createActionSheet({
      header: 'Actions',
      buttons: [
        {
          text: 'Add Note',
          handler: async () => {
            await this.addNote();
          },
        },
        {
          text: 'Create Image',
          handler: () => {
            this.showAddImage();
          },
        },
        {
          text: 'Copy Verse',
          handler: () => {
            this.copyVerse();
          },
        },
        {
          text: 'Edit Tags',
          handler: async () => {
            await this.editTags();
          },
        },
        {
          text: 'Cancel',
          role: 'cancel',
        },
      ],
    });
  }

  showAddImage() {
    this.shouldShowAddImage.set(true);
  }

  async handleTagClicked(tag: Tag) {
    await this.router.navigate([getRoutePath(favoritesRoutePath)], {
      queryParams: { tagIds: tag.id.toString() },
    });
  }

  private async copyVerse() {
    try {
      const verse = await firstValueFrom(this.verse$);
      const verses =
        verse.end_verse && verse.end_verse !== verse.start_verse
          ? `${verse.start_verse}-${verse.end_verse}`
          : verse.start_verse;
      const verseContentNoMarkdown = verse.content
        ?.replaceAll(/<sup>\s*[0-9]+\s*<\/sup>\s?/g, '')
        ?.trim();
      const content = `"${verseContentNoMarkdown}"\n\n${verse.book} ${verse.chapter}:${verses}`;
      await this.clipboardService.copyToClipboard(content);
      await this.alertService.createNotice({
        message: 'Copied!',
        duration: 5000,
        positionAnchor: 'footer',
      });
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : 'An error occurred';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
      });
    }
  }

  private createImageAttachments(images: Image[]) {
    return images.map(
      (image) => ({ ...image, type: 'Image' } as ImageAttachment)
    );
  }

  private createNoteAttachments(notes: Note[]) {
    return notes.map((note) => ({ ...note, type: 'Note' } as NoteAttachment));
  }

  private sortDescending(a: Attachment, b: Attachment) {
    const getComparisonTime = (attachment: Attachment) => {
      // Always use created_at for consistent ordering to prevent notes from jumping when edited
      return new Date(attachment.created_at!).getTime();
    };

    return getComparisonTime(b) - getComparisonTime(a);
  }

  async handleRegenerateImage(image: ImageAttachment) {
    if (!image.prompt) {
      await this.alertService.createNotice({
        message: 'Cannot regenerate this image as it has no prompt stored',
        duration: 5000,
        positionAnchor: 'footer',
      });
      return;
    }

    this.loadingService.setLoading(true);

    try {
      const verse = await firstValueFrom(this.verse$);
      if (!verse.content) {
        throw new Error('Verse content is empty');
      }

      // All images are now square
      const { quote, source } = this.verseQuoteFactory.create(verse, 'square');
      const theme: ImageTheme = {
        type: ImageThemeType.Custom,
        content: image.prompt,
      };

      // Resolve the stored model to a valid Venice model
      const { model: veniceModel, wasRemapped, originalProvider } = resolveModel(image.model);

      // Notify user if we're using a different model than the original
      if (wasRemapped && originalProvider) {
        const newModelInfo = getModelInfo(veniceModel);
        await this.alertService.createNotice({
          message: `Original model "${originalProvider}" unavailable. Using ${newModelInfo.name}.`,
          duration: 4000,
          positionAnchor: 'footer',
        });
      }

      await this.imagesService.generateImage(
        verse.id!,
        quote,
        source,
        theme,
        veniceModel
      );

      this.refresh$.next();
      // Refresh credit balance after successful generation
      await this.loadCreditBalance();
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : 'An error occurred';
      await this.alertService.createNotice({
        message,
        duration: 5000,
        positionAnchor: 'footer',
      });
    } finally {
      this.loadingService.setLoading(false);
    }
  }

  private get id$() {
    return this.route.paramMap.pipe(
      map((params) => {
        const param = params.get('id');
        const id = Number(param);
        if (isNaN(id)) {
          throw new Error('Invalid ID');
        }
        return id;
      })
    );
  }
}
