import { CommonModule } from '@angular/common';
import { Component, EventEmitter, inject, Input, OnInit, Output, Pipe, PipeTransform } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  ActionSheetController,
  IonButton,
  IonCard,
  IonCardContent,
  IonCardHeader,
  IonCardTitle,
  IonIcon,
  IonSelect,
  IonSelectOption,
  IonTextarea,
  IonLabel,
  IonItem,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { alertCircleOutline } from 'ionicons/icons';
import { AlertService } from 'src/app/common/alert/alert.service';
import { CreditsService, CreditPackage } from 'src/app/common/credits/credits.service';
import { LocalStorageService } from 'src/app/common/storage/local-storage.service';
import {
  VeniceImageModel,
  VENICE_IMAGE_MODELS,
  DEFAULT_VENICE_MODEL,
} from 'src/app/images/images.service';
import { ImageThemeType, ImageTheme } from 'supabase/functions/images/themes';

@Pipe({
  name: 'formatTheme',
  standalone: true
})
export class FormatThemePipe implements PipeTransform {
  transform(value: string): string {
    // Replace underscores with spaces and apply title case
    const withSpaces = value.replace(/_/g, ' ');
    return withSpaces.replace(/\w\S*/g, (txt) => {
      return txt.charAt(0).toUpperCase() + txt.substring(1).toLowerCase();
    });
  }
}

@Component({
    selector: 'app-add-image-card',
    templateUrl: './add-image-card.component.html',
    styleUrls: ['./add-image-card.component.scss'],
    imports: [
    CommonModule,
    IonIcon,
    IonCard,
    IonCardHeader,
    IonCardTitle,
    IonButton,
    IonCardContent,
    FormsModule,
    IonSelect,
    IonSelectOption,
    IonTextarea,
    IonLabel,
    IonItem,
    FormatThemePipe
]
})
export class AddImageCardComponent implements OnInit {
  private actionSheetCtrl = inject(ActionSheetController);
  private alertService = inject(AlertService);
  private creditsService = inject(CreditsService);
  private localStorageService = inject(LocalStorageService);
  private _wordCount = 0;

  closeIcon = 'node_modules/openmoji/color/svg/E24E.svg'; // ⏹️ Close Button

  @Input()
  set verseContent(value: string) {
    this._wordCount = value.split(/\s+/).length;
  }

  @Input() creditBalance = 0;

  @Output() addImageClosed = new EventEmitter<void>();
  @Output() createImage = new EventEmitter<{ theme: ImageTheme; veniceModel: VeniceImageModel }>();

  selectedTheme: ImageThemeType = ImageThemeType.Landscape;
  selectedVeniceModel: VeniceImageModel = DEFAULT_VENICE_MODEL;
  customPrompt = '';
  themeTypes = Object.values(ImageThemeType);
  veniceModels = VENICE_IMAGE_MODELS;

  ngOnInit() {
    // Load the preferred Venice model from local storage
    const preferredModel = this.localStorageService.getItem('preferred-venice-model') as VeniceImageModel | null;
    if (preferredModel && VENICE_IMAGE_MODELS.some(m => m.id === preferredModel)) {
      this.selectedVeniceModel = preferredModel;
    }
  }

  get showWarning(): boolean {
    // Word limit for square images is 40
    return this._wordCount > 40;
  }

  get isCustomTheme(): boolean {
    return this.selectedTheme === ImageThemeType.Custom;
  }

  get selectedModelCost(): number {
    const model = VENICE_IMAGE_MODELS.find(m => m.id === this.selectedVeniceModel);
    return model?.cost ?? 1;
  }

  get hasCredits(): boolean {
    return this.creditBalance >= this.selectedModelCost;
  }

  get isCreateDisabled(): boolean {
    return !this.hasCredits;
  }

  onVeniceModelChange() {
    // Save the selected model to local storage
    this.localStorageService.setItem('preferred-venice-model', this.selectedVeniceModel);
  }

  onClose() {
    this.addImageClosed.emit();
  }

  constructor() {
    addIcons({ alertCircleOutline });
  }

  onCreateImage() {
    if (this.creditBalance < this.selectedModelCost) {
      return;
    }

    const theme: ImageTheme = {
      type: this.selectedTheme,
      ...(this.isCustomTheme && { content: this.customPrompt })
    };

    this.createImage.emit({
      theme,
      veniceModel: this.selectedVeniceModel
    });
  }

  async onGetCredits() {
    const packages = await this.creditsService.getPackages();

    if (packages.length === 0) {
      this.alertService.createNotice({
        message: 'No credit packages available',
        duration: 3000,
        positionAnchor: 'footer',
      });
      return;
    }

    const buttons: Array<{ text: string; role?: string; handler?: () => void }> = packages.map((pkg: CreditPackage) => ({
      text: `${pkg.credits} credits - ${pkg.priceFormatted}`,
      handler: () => { this.purchasePackage(pkg); },
    }));

    buttons.push({
      text: 'Cancel',
      role: 'cancel',
    });

    const actionSheet = await this.actionSheetCtrl.create({
      header: 'Purchase Credits',
      buttons,
    });

    await actionSheet.present();
  }

  private async purchasePackage(pkg: CreditPackage) {
    try {
      const url = await this.creditsService.purchasePackage(pkg.id);
      if (url) {
        // Web flow: redirect to Stripe Checkout
        window.location.href = url;
      }
      // Native flow: Browser was opened, deep link will return user to app
    } catch (error) {
      console.error('Purchase error:', error);
      this.alertService.createNotice({
        message: 'Failed to start checkout. Please try again.',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
    }
  }
}
